  let out = '';
  for (const r of rows) {
    for (const item of r.items) {
      if (item.qty > 0) {
        if (item.discount) {
          out += `${item.name}: ${item.qty} @ ${item.price} (-${item.discount})\n`;
        } else {
          out += `${item.name}: ${item.qty} @ ${item.price}\n`;
        }
      }
    }
  }
